// test/webviewSourceSync.check.ts
//
// Plan p21-t1: media/main.js is generated by concatenating
// media/src/main/*.js (in filename order) via scripts/build-webview.mjs.
// This test guards against drift between the source parts and the
// committed, tracked media/main.js without depending on ESM import
// interop (this project's tsconfig compiles to CommonJS, and
// build-webview.mjs is ESM) — it just re-runs the check script as a
// subprocess, the same way `npm run check:webview-sync` does.

import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import path from "node:path";

const REPO_ROOT = path.resolve(__dirname, "..", "..");

test("media/main.js is in sync with media/src/main/*.js", () => {
  const scriptPath = path.join(REPO_ROOT, "scripts", "check-webview-sync.mjs");
  assert.doesNotThrow(() => {
    execFileSync("node", [scriptPath], { cwd: REPO_ROOT, stdio: "pipe" });
  }, "media/main.js is out of sync — run `npm run build:webview` and commit the result.");
});
